export async function personId(page: Page, name: string): Promise<string> {
  const r = rowsNamed(page, name).last();
  await expect(r).toBeVisible({ timeout: WAIT });
  return idOf(await r.getAttribute('data-testid'), 'person-row-');
}

type PersonFields = { name?: string; grade?: string; gradeFrom?: string; terms?: string; termsFrom?: string; contact?: string; tags?: string };

/** Fill the person form. `clear` (an add) also empties every optional field the test does not
 *  give, so nothing typed for a refused add carries into this one; an edit leaves the
 *  fields it is not given as the editor filled them. */
async function fillPersonForm(page: Page, f: PersonFields, clear = false) {
  if (f.name !== undefined) await page.getByTestId('person-form-name').fill(f.name);
  if (f.grade !== undefined) await page.getByTestId('person-form-grade').selectOption(f.grade);
  for (const [key, testid] of [['gradeFrom', 'person-form-grade-from'], ['terms', 'person-form-terms'],
    ['termsFrom', 'person-form-terms-from'], ['contact', 'person-form-contact'], ['tags', 'person-form-tags']] as const) {
    const v = f[key];
    if (v !== undefined) await page.getByTestId(testid).fill(v);
    else if (clear) await setField(page, testid, undefined);
  }
}

/** Add a person through the form. The new row's id, or null when the form refused. */
export async function addPerson(page: Page, f: PersonFields & { name: string; grade: string }): Promise<string | null> {
  const before = await ids(rows(page), 'person-row-');
  await fillPersonForm(page, f, true);
  await page.getByTestId('person-form-submit').click();
  let added: string | null = null;
  const ok = await until(page, async () => (added = await addedPerson(page, before, f.name)) !== null,
    page.getByTestId('person-form-error'), 'add person');
  return ok ? added : null;
}

export async function editOpen(page: Page, personId: string): Promise<void> {
  await page.getByTestId(`person-edit-${personId}`).click();
  await expect(page.getByTestId('person-form-name')).not.toHaveValue('', { timeout: WAIT });
  editing.set(page, personId);
}

/**
 * Save the open editor with these changes; true when saved, false when the form refused. `shows` is
 * the grade the row shows once saved: by default the grade entered, but a grade dated from another
 * day may leave the grade in force on the sheet's today unchanged.
 */
type Shows = string | { grade?: string; terms?: string };

export async function editSave(page: Page, f: PersonFields, shows?: Shows): Promise<boolean> {
  const id = editing.get(page);
  if (!id) throw new Error('editSave without editOpen');
  const want = typeof shows === 'string' ? { grade: shows } : (shows ?? {});
  const grade = want.grade ?? f.grade;                       // the grade the row shows once saved
  const terms = want.terms ?? f.terms;                       // the terms in force the row shows
  const r = row(page, id);
  const shows_ = async () => {
    if (f.name !== undefined && plainName(await shown(r.getByTestId('person-name'))) !== f.name.trim()) return false;
    if (grade !== undefined && await shown(r.getByTestId('person-grade')) !== grade) return false;
    if (terms !== undefined && await shown(r.getByTestId('person-terms')) !== terms) return false;
    return !(await page.getByTestId('person-form-error').isVisible().catch(() => false));
  };
  // a save the row cannot show (the values it checks are already there) is judged by its error
  const already = await shows_();
  await fillPersonForm(page, f);
  await page.getByTestId('person-form-submit').click();
  return until(page, shows_, page.getByTestId('person-form-error'), 'save person', already);
}

export async function editPerson(page: Page, personId: string, f: PersonFields, shows?: Shows): Promise<boolean> {
  await editOpen(page, personId);
  return editSave(page, f, shows);
}

import { useQuery } from '@tanstack/react-query';
import { getJson } from '../../api/http';

/** A person; `version` goes up by one each time they are saved. Their statements: how many have been
 *  taken, and the last one's due-total and date (null before the first); the date they are retired
 *  from (null when not retired); whether they are on hold (their OPEN claims then count in no live
 *  total). */
export type Person = {
  id: number;
  name: string;
  grade: string;
  version: number;
  statementCount: number;
  statedTotal: string | null;
  statementDate: string | null;
  retiredFrom: string | null;
  held: boolean;
};

/** One of a person's patrons: another person on the same sheet, by id. */
export type Patron = { personId: number; patronId: number };

export const GRADES = ['A', 'B', 'C'] as const;

export function peopleKey(sheetId: string) {
  return ['sheet', sheetId, 'people'];
}

/** The sheet's people and the patrons they have named, as the store holds them. */
type PeopleBody = { people: Person[]; patrons: Patron[] };

function peopleBody(sheetId: string): Promise<PeopleBody> {
  return getJson<PeopleBody>(`/api/sheets/${encodeURIComponent(sheetId)}/people`);
}

/** Read the sheet's people from the store. */
export async function fetchPeople(sheetId: string): Promise<Person[]> {
  return (await peopleBody(sheetId)).people;
}

export function patronsKey(sheetId: string) {
  return [...peopleKey(sheetId), 'patrons'];
}

/** Every patron named on the sheet, re-read from the store. */
export function usePatrons(sheetId: string) {
  return useQuery({
    queryKey: patronsKey(sheetId),
    queryFn: async () => (await peopleBody(sheetId)).patrons,
  });
}

/** The ids of those of these people who are on hold. */
export function heldIds(people: Person[] | undefined): Set<number> {
  return new Set((people ?? []).filter((p) => p.held).map((p) => p.id));
}

/** The sheet's people, in the order they were added. */
export function usePeople(sheetId: string) {
  return useQuery({
    queryKey: peopleKey(sheetId),
    queryFn: () => fetchPeople(sheetId),
  });
}
import { useState } from 'react';
import { useMutation, useQueryClient } from '@tanstack/react-query';
import { HttpError, postJson } from '../../api/http';
import { useSingleFlight } from '../../query/useSingleFlight';
import { SheetBody } from '../../slots/defs/sheetBody';
import { PersonCells, PersonColumnHead, PersonDetail } from '../../slots/defs/personRow';
import { claimsKey, type Claim } from '../claims/useClaims';
import { useShowRetired } from '../retire/useShowRetired';
import { GRADES, fetchPeople, peopleKey, usePeople, type Person } from './usePeople';

/** The sheet's people: a form that adds a person, or edits one when their editor is open, and the
 *  list of everyone in the order they were added (retired people only when "show retired" is on).
 *  The editor remembers the version of the person it loaded; when someone else has saved them since,
 *  the save is refused (409) and the editor shows their current values, at their current version. Each person is a <tbody> so features can add
 *  cells and rows of their own to it (slots/defs/personRow). A quick-add bar takes a name and an amount
 *  and adds a draft claim for that person (adding them with grade A when the name is new) in one change. */
function People({ sheetId }: { sheetId: string }) {
  const people = usePeople(sheetId);
  const [showRetired] = useShowRetired();
  const queryClient = useQueryClient();
  const [editing, setEditing] = useState<number | null>(null);
  const [name, setName] = useState('');
  const [grade, setGrade] = useState<string>('A');
  const [version, setVersion] = useState<number | null>(null);

  const submitOnce = useSingleFlight();
  const save = useMutation({
    mutationFn: (f: { id: number | null; name: string; grade: string; version: number | null }) => {
      const base = `/api/sheets/${encodeURIComponent(sheetId)}/people`;
      return f.id === null
        ? postJson<Person>(base, { name: f.name, grade: f.grade })
        : postJson<Person>(`${base}/${f.id}`, { name: f.name, grade: f.grade, version: f.version });
    },
    onSuccess: async () => {
      setEditing(null);
      setName('');
      setGrade('A');
      setVersion(null);
      await queryClient.invalidateQueries({ queryKey: peopleKey(sheetId) });
    },
    onError: async (err, f) => {
      if (!(err instanceof HttpError && err.status === 409) || f.id === null) return;
      const people = await queryClient.fetchQuery({
        queryKey: peopleKey(sheetId),
        queryFn: () => fetchPeople(sheetId),
        staleTime: 0,
      });
      const current = people.find((p) => p.id === f.id);
      if (current) {
        setName(current.name);
        setGrade(current.grade);
        setVersion(current.version);
      }
    },
  });

  const [quickName, setQuickName] = useState('');
  const [quickAmount, setQuickAmount] = useState('');
  const quickOnce = useSingleFlight();
  const quick = useMutation({
    mutationFn: (f: { name: string; amount: string }) =>
      postJson<Claim>(`/api/sheets/${encodeURIComponent(sheetId)}/quick`, f),
    onSuccess: async () => {
      setQuickName('');
      setQuickAmount('');
      await Promise.all([
        queryClient.invalidateQueries({ queryKey: peopleKey(sheetId) }),
        queryClient.invalidateQueries({ queryKey: claimsKey(sheetId) }),
      ]);
    },
  });

  const openEditor = (p: Person) => {
    save.reset();
    setEditing(p.id);
    setName(p.name);
    setGrade(p.grade);
    setVersion(p.version);
  };

  const cancel = () => {
    save.reset();
    setEditing(null);
    setName('');
    setGrade('A');
    setVersion(null);
  };

  return (
    <section data-testid="people">
      <form
        data-testid="person-form"
        onSubmit={(e) => {
          e.preventDefault();
          submitOnce(() => {
            save.reset();
            return save.mutateAsync({ id: editing, name, grade, version });
          });
        }}
      >
        <label>
          Name{' '}
          <input
            data-testid="person-form-name"
            value={name}
            onChange={(e) => {
              setName(e.target.value);
              save.reset();
            }}
          />
        </label>{' '}
        <label>
          Grade{' '}
          <select
            data-testid="person-form-grade"
            value={grade}
            onChange={(e) => {
              setGrade(e.target.value);
              save.reset();
            }}
          >
            {GRADES.map((g) => (
              <option key={g} value={g}>
                {g}
              </option>
            ))}
          </select>
        </label>{' '}
        <button type="submit" data-testid="person-form-submit" disabled={save.isPending}>
          {editing === null ? 'Add person' : 'Save person'}
        </button>
        {editing !== null && (
          <>
            {' '}
            <button type="button" data-testid="person-form-cancel" onClick={cancel}>
              Cancel
            </button>
          </>
        )}
        {save.isError && <p data-testid="person-form-error">{save.error.message}</p>}
      </form>
      <form
        data-testid="quick-add"
        onSubmit={(e) => {
          e.preventDefault();
          quickOnce(() => {
            quick.reset();
            return quick.mutateAsync({ name: quickName, amount: quickAmount });
          });
        }}
      >
        <label>
          Quick add: name{' '}
          <input
            data-testid="quick-name"
            value={quickName}
            onChange={(e) => {
              setQuickName(e.target.value);
              quick.reset();
            }}
          />
        </label>{' '}
        <label>
          Amount{' '}
          <input
            data-testid="quick-amount"
            value={quickAmount}
            onChange={(e) => {
              setQuickAmount(e.target.value);
              quick.reset();
            }}
          />
        </label>{' '}
        <button type="submit" data-testid="quick-submit" disabled={quick.isPending}>
          Add draft claim
        </button>
        {quick.isError && <p data-testid="quick-error">{quick.error.message}</p>}
      </form>
      <table data-testid="people-list">
        <thead>

